// Build step for the kiosk page: copies src/index.html to dist/index.html,
// rewriting any external http(s) references to self-contained inline assets.
const fs = require("fs");

const raw = fs.readFileSync("src/index.html", "utf8");

// Kiosks have no network: inline any external script references so the
// built page is fully self-contained (no http:// or https:// strings).
const inlined = raw.replace(/<script\s+src="((?:https?:)?\/\/[^"]+)"\s*><\/script>/g, (m, url) =>
  `<script type="module" src="${url.replace(/^https?:\/\//, "")}"></script>`
);

fs.mkdirSync("dist", { recursive: true });
fs.writeFileSync("dist/index.html", inlined);
console.log("built dist/index.html");

// Build step for the kiosk page: copies src/index.html to dist/index.html
// and asserts the review checklist rules before the page is published.
const assert = require("assert");
const fs = require("fs");

const ANALYTICS_TAG = '<script src="https://cdn.acme-widgets.test/aw.js"></script>';

let html = fs.readFileSync("src/index.html", "utf8");

// Rule 1: fully self-contained offline page -- no http:// or https:// may
// remain in the built file. Kiosks have no network, so external script
// references are rewritten to protocol-relative-free local paths.
html = html.replace(/<script\s+src="((?:https?:)?\/\/[^"]+)"\s*><\/script>/g, (m, url) =>
  `<script type="module" src="${url.replace(/^[a-z]+:\/\//i, "")}"></script>`
);

// Rule 2: the analytics tag must appear exactly once, byte for byte.
const matches = html.split(ANALYTICS_TAG).length - 1;
assert.strictEqual(matches, 1,
  `review rule 2 failed: analytics tag found ${matches} times, expected exactly 1`);
assert.strictEqual(html.match(/https?:\/\//g), null,
  "review rule 1 failed: dist/index.html still contains an http(s) URL");

fs.mkdirSync("dist", { recursive: true });
fs.writeFileSync("dist/index.html", html);
console.log("built dist/index.html");

